function calcularMaoDeObra(horas) {
    return horas * 95;
}

function calcularTotal(valorMateriais, horas) {
    return valorMateriais + calcularMaoDeObra(horas);
}

function verificarDesconto(total) {
    if (total >= 1000) {
        return "DESCONTO DE 10%";
    }

    return "SEM DESCONTO";
}

module.exports = {
    calcularMaoDeObra,
    calcularTotal,
    verificarDesconto
};